import io
from collections.abc import Iterator
from datetime import UTC, datetime, timedelta, timezone

import pytest

from runlog import ParseError, RunRecord, Status, parse_line, summarize

# --- parse_line -------------------------------------------------------------


def test_parse_line_reads_all_four_fields() -> None:
    record = parse_line("2026-10-19T07:01:02Z PASS test_login 132ms")

    assert isinstance(record, RunRecord)
    assert record.timestamp == datetime(2026, 10, 19, 7, 1, 2, tzinfo=UTC)
    assert record.status is Status.PASS
    assert record.test_id == "test_login"
    assert record.duration_ms == 132


@pytest.mark.parametrize(
    ("raw", "expected"),
    [("PASS", Status.PASS), ("FAIL", Status.FAIL), ("SKIP", Status.SKIP)],
)
def test_parse_line_maps_each_status(raw: str, expected: Status) -> None:
    record = parse_line(f"2026-10-19T07:01:02Z {raw} test_x 1ms")

    assert record.status is expected


def test_parse_line_tolerates_extra_whitespace_and_newline() -> None:
    line = "  2026-10-19T07:01:02Z \t FAIL   tests/api.py::test_x   0ms \n"

    record = parse_line(line)

    assert record.status is Status.FAIL
    assert record.test_id == "tests/api.py::test_x"
    assert record.duration_ms == 0


def test_parse_line_keeps_a_utc_offset() -> None:
    record = parse_line("2026-10-19T09:01:02+02:00 PASS test_x 1ms")

    assert record.timestamp.utcoffset() == timedelta(hours=2)
    plus_two = timezone(timedelta(hours=2))
    assert record.timestamp == datetime(2026, 10, 19, 9, 1, 2, tzinfo=plus_two)


@pytest.mark.parametrize(
    "line",
    [
        pytest.param("", id="empty"),
        pytest.param("   ", id="blank"),
        pytest.param("# a comment", id="comment"),
        pytest.param("garbage", id="one-field"),
        pytest.param("2026-10-19T07:01:02Z PASS test_x", id="missing-duration"),
        pytest.param("2026-10-19T07:01:02Z PASS test_x 1ms extra", id="five-fields"),
        pytest.param("2026-10-19T07:01:02Z pass test_x 1ms", id="lowercase-status"),
        pytest.param("2026-10-19T07:01:02Z ERROR test_x 1ms", id="unknown-status"),
        pytest.param(
            "2026-10-19T07:01:02Z PASS test_x 132", id="duration-without-unit"
        ),
        pytest.param(
            "2026-10-19T07:01:02Z PASS test_x 1.5ms", id="fractional-duration"
        ),
        pytest.param("2026-10-19T07:01:02Z PASS test_x -5ms", id="negative-duration"),
        pytest.param("2026-10-19T07:01:02Z PASS test_x ms", id="unit-without-number"),
        pytest.param("2026-13-40T07:01:02Z PASS test_x 1ms", id="impossible-date"),
        pytest.param("yesterday PASS test_x 1ms", id="not-a-timestamp"),
        pytest.param("2026-10-19T07:01:02 PASS test_x 1ms", id="naive-timestamp"),
    ],
)
def test_parse_line_rejects_invalid_lines(line: str) -> None:
    with pytest.raises(ParseError):
        parse_line(line)


def test_parse_error_is_a_value_error() -> None:
    assert issubclass(ParseError, ValueError)


def test_run_record_is_immutable() -> None:
    record = parse_line("2026-10-19T07:01:02Z PASS test_x 1ms")
    field = "status"

    with pytest.raises(AttributeError):
        setattr(record, field, Status.FAIL)


def test_run_record_compares_by_value() -> None:
    line = "2026-10-19T07:01:02Z PASS test_x 1ms"

    assert parse_line(line) == parse_line(line)


# --- summarize --------------------------------------------------------------

LOG = """\
# nightly run
2026-10-19T07:00:00Z PASS test_login 120ms
2026-10-19T07:00:01Z FAIL test_checkout 300ms
2026-10-19T07:00:02Z SKIP test_refund 0ms

2026-10-19T07:00:03Z PASS test_search 300ms
2026-10-19T07:00:04Z PASS test_checkout 280ms
2026-10-19T07:00:05Z SKIP test_login 0ms
"""


def test_summarize_counts_every_record_line() -> None:
    summary = summarize(LOG.splitlines())

    assert summary.total == 6
    assert summary.passed == 3
    assert summary.failed == 1
    assert summary.skipped == 2


def test_summarize_pass_rate_excludes_skips() -> None:
    summary = summarize(LOG.splitlines())

    assert summary.pass_rate == pytest.approx(0.75)


def test_summarize_slowest_takes_the_first_on_a_tie() -> None:
    summary = summarize(LOG.splitlines())

    expected = parse_line("2026-10-19T07:00:01Z FAIL test_checkout 300ms")
    assert summary.slowest == expected


def test_summarize_flaky_needs_both_a_pass_and_a_fail() -> None:
    summary = summarize(LOG.splitlines())

    assert isinstance(summary.flaky, frozenset)
    assert summary.flaky == {"test_checkout"}


def test_summarize_skip_never_makes_a_test_flaky() -> None:
    lines = [
        "2026-10-19T07:00:00Z PASS test_a 1ms",
        "2026-10-19T07:00:01Z SKIP test_a 0ms",
        "2026-10-19T07:00:02Z FAIL test_b 1ms",
        "2026-10-19T07:00:03Z SKIP test_b 0ms",
    ]

    assert summarize(lines).flaky == frozenset()


def test_summarize_empty_log() -> None:
    summary = summarize([])

    assert summary.total == 0
    assert summary.passed == 0
    assert summary.failed == 0
    assert summary.skipped == 0
    assert summary.pass_rate is None
    assert summary.slowest is None
    assert summary.flaky == frozenset()


def test_summarize_only_comments_and_blanks_is_empty() -> None:
    summary = summarize(["# header", "", "   ", "  # indented comment"])

    assert summary.total == 0
    assert summary.pass_rate is None


def test_summarize_pass_rate_is_none_when_everything_skipped() -> None:
    lines = [
        "2026-10-19T07:00:00Z SKIP test_a 0ms",
        "2026-10-19T07:00:01Z SKIP test_b 0ms",
    ]

    summary = summarize(lines)

    assert summary.skipped == 2
    assert summary.pass_rate is None


def test_summarize_pass_rate_zero_when_everything_failed() -> None:
    lines = [
        "2026-10-19T07:00:00Z FAIL test_a 1ms",
        "2026-10-19T07:00:01Z FAIL test_b 1ms",
    ]

    assert summarize(lines).pass_rate == 0.0


def test_summarize_reports_the_line_number_of_a_bad_line() -> None:
    lines = [
        "# header",
        "2026-10-19T07:00:00Z PASS test_a 1ms",
        "",
        "2026-10-19T07:00:01Z BROKEN test_b 1ms",
    ]

    with pytest.raises(ParseError, match=r"\bline 4\b"):
        summarize(lines)


def test_summarize_accepts_a_generator() -> None:
    def generate() -> Iterator[str]:
        yield "2026-10-19T07:00:00Z PASS test_a 5ms"
        yield "2026-10-19T07:00:01Z FAIL test_a 9ms"

    summary = summarize(generate())

    assert summary.total == 2
    assert summary.flaky == {"test_a"}
    assert summary.slowest is not None
    assert summary.slowest.duration_ms == 9


def test_summarize_accepts_an_open_file() -> None:
    summary = summarize(io.StringIO(LOG))

    assert summary.total == 6
    assert summary.pass_rate == pytest.approx(0.75)


def test_run_summary_is_immutable() -> None:
    summary = summarize([])
    field = "total"

    with pytest.raises(AttributeError):
        setattr(summary, field, 1)
